{"cards": [{"node_code": "N_51c0d9f0d7dc1a40", "definition": "研究肿瘤细胞表面或内部特异性抗原的识别机制，以及肿瘤细胞通过下调MHC、分泌抑制因子或招募抑制性细胞等方式逃避宿主免疫系统监视的生物学过程。", "boundary": "本节点聚焦于肿瘤免疫的“基础机制”与“病理过程”，即肿瘤如何被识别及如何逃逸。涵盖肿瘤特异性抗原（TSA）、肿瘤相关抗原（TAA）、MHC分子表达异常、PD-L1上调及免疫微环境中的抑制性机制。与“肿瘤免疫治疗”的区别在于，本节点侧重解释“为什么”肿瘤能逃逸（机制），而非“如何”利用这些机制进行干预（治疗）。", "includes": ["肿瘤特异性抗原与肿瘤相关抗原的分类及识别", "肿瘤细胞免疫逃逸机制（如MHC下调、抗原加工缺陷）", "肿瘤微环境中免疫抑制因子的作用机制"], "excludes": ["基于免疫逃逸机制开发的药物临床试验数据（归入肿瘤免疫治疗）", "非免疫介导的肿瘤转移或耐药机制（归入肿瘤生物学）"], "sibling_distinctions": [{"other_code": "N_5de38977a21614e4", "rule": "本节点侧重肿瘤抗原识别与免疫逃逸的生物学机制研究；肿瘤免疫治疗侧重利用这些机制开发的治疗策略、药物及临床应用。"}], "cross_boundary_rule": "若内容涉及免疫检查点分子（如PD-1/PD-L1）的结构与功能机制，主挂载本节点；若涉及抗PD-1/PD-L1药物的疗效、副作用或联合用药方案，主挂载肿瘤免疫治疗。"}, {"node_code": "N_5de38977a21614e4", "definition": "研究利用免疫系统原理清除肿瘤细胞的治疗策略，包括免疫检查点抑制剂、过继性细胞治疗（如CAR-T、TIL）、肿瘤疫苗及细胞因子治疗等临床干预手段。", "boundary": "本节点聚焦于肿瘤免疫的“临床应用”与“干预策略”，即如何激活或增强免疫系统以对抗肿瘤。涵盖各类免疫治疗药物的作用靶点、给药方案、疗效评估及免疫相关不良反应（irAEs）的管理。与“肿瘤抗原与免疫逃逸”的区别在于，本节点侧重“治疗”与“干预”，而非基础机制的阐释。", "includes": ["免疫检查点抑制剂（如抗PD-1、抗CTLA-4）的临床应用", "过继性细胞治疗（CAR-T、TIL、TCR-T）的原理与实施", "肿瘤疫苗、细胞因子治疗及免疫相关不良反应管理"], "excludes": ["传统化疗、放疗或靶向治疗（非免疫机制）（归入肿瘤学或放射医学）", "免疫逃逸的基础分子机制研究（归入肿瘤抗原与免疫逃逸）"], "sibling_distinctions": [{"other_code": "N_51c0d9f0d7dc1a40", "rule": "本节点侧重基于免疫机制的治疗策略、药物及临床管理；肿瘤抗原与免疫逃逸侧重抗原识别与逃逸的生物学基础机制。"}], "cross_boundary_rule": "若内容涉及免疫治疗药物的研发原理或作用机制，主挂载本节点；若涉及具体药物的临床试验结果、适应症或副作用处理，主挂载本节点；若涉及基础免疫分子结构，可关联肿瘤抗原与免疫逃逸。"}]}
